#include <stdio.h>

void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

void getMinMax(int arr[], int n, int* min, int* max) {
    *min = *max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < *min) *min = arr[i];
        if (arr[i] > *max) *max = arr[i];
    }
}

int main() {
    int x=3, y=5;
    swap(&x, &y);
    printf("%d %d\n", x, y);  // 5 3
    return 0;
}

