// 综合应用：函数指针+结构体+位运算
#include <stdio.h>

typedef struct {
    volatile unsigned int* reg;
    void (*setBit)(volatile unsigned int*, int);
} GPIO_Handler;

void setBitImpl(volatile unsigned int* reg, int n) {
    *reg |= (1 << n);
}

int main() {
    unsigned int mockReg = 0;
    GPIO_Handler h = {&mockReg, setBitImpl};
    h.setBit(h.reg, 3);
    printf("reg=0x%x\n", mockReg);  // 0x8
    return 0;
}

// 位操作函数封装
#define SET_BIT(reg, n)    ((reg) |= (1U << (n)))
#define CLR_BIT(reg, n)    ((reg) &= ~(1U << (n)))
#define TOG_BIT(reg, n)    ((reg) ^= (1U << (n)))
#define GET_BIT(reg, n)    (((reg) >> (n)) & 1U)

#include <stdio.h>
int main() {
    unsigned int reg = 0x00;
    SET_BIT(reg, 5);       // reg=0x20
    SET_BIT(reg, 3);       // reg=0x28
    CLR_BIT(reg, 5);       // reg=0x08
    TOG_BIT(reg, 3);       // reg=0x00
    printf("bit3=%d\n", GET_BIT(reg, 3));  // 0
    return 0;
}
